import {WATER_STRUCTURES} from './utilities.js?v=learning-city-1';
import {waterBaseNeed} from './utility-demand.js?v=learning-city-1';
import {conservationDemand} from './conservation.js?v=learning-city-1';
import {pipeCoverage} from './water-coverage.js?v=learning-city-1';
const number=n=>n.toLocaleString('en-US',{maximumFractionDigits:1});
export function waterGridData(city){
 const groups=(city.stats.waterNetworks||[]).map((g,id)=>({...g,id,nodes:[],pipes:[],sources:[]})),uncovered=[];
 for(let i=0;i<city.tiles.length;i++){const t=city.tiles[i],g=groups[t.waterNetwork];if(g){g.nodes.push(i);if(t.pipe)g.pipes.push(i);if(WATER_STRUCTURES[t.type])g.sources.push(i);}if(waterBaseNeed(t)>0&&!t.waterCovered)uncovered.push(i);}
 const scratch=new Uint8Array(city.tiles.length).fill(255);
 const networks=groups.map(g=>{const reached=pipeCoverage(city.size,g.pipes,scratch).filter(i=>waterBaseNeed(city.tiles[i])>0),missing=reached.filter(i=>!city.tiles[i].watered),demand=reached.reduce((sum,i)=>sum+conservationDemand(city,'water',waterBaseNeed(city.tiles[i])),0);return{...g,demand,unwatered:missing.length,anchor:missing[0]??g.sources[0]??g.nodes[0],status:!g.pipeCount?'No connected pipes':missing.length?g.capacity>0?'Supply shortage':'No supply':reached.length?'Supplied':'No demand'};});
 return{networks,uncovered,sources:city.tiles.flatMap((t,i)=>WATER_STRUCTURES[t.type]?[{tile:i,name:WATER_STRUCTURES[t.type].name,age:t.age,output:t.pumpCapacity,loss:t.pollutionCapacityLoss,efficiency:t.waterEfficiency,grid:t.waterNetwork,cost:WATER_STRUCTURES[t.type].cost,treatment:t.type==='waterTreatment',active:t.treatmentActive}]:[])};
}
export function waterGridReport(city){const {networks,uncovered,sources}=waterGridData(city);return `<h3>Water networks</h3><p>Water must reach each neighborhood through connected pipes. Spare supply on another network does not flow into these pipes. Available supply includes current imports and exports; delivered is the amount this network actually supplies.</p><div class="table-scroll" style="max-height:360px;overflow:auto"><table><thead><tr><th>Network</th><th>Status</th><th>Available / delivered</th><th>Reachable demand</th><th>Unwatered tiles</th><th>Location</th></tr></thead><tbody>${networks.map(g=>`<tr><td>${g.id+1}</td><td>${g.status}</td><td>${number(g.capacity)} / ${number(g.used)}</td><td>${number(g.demand)}</td><td>${g.unwatered}</td><td><button data-water-location="${g.anchor}">View ${g.unwatered?'shortage':'network'}</button></td></tr>`).join('')||'<tr><td colspan="6">No water networks yet. Build a powered source and connect pipes.</td></tr>'}</tbody></table></div><p>Reachable demand includes empty zoning within seven tiles of this network’s pipes. Coverage can overlap: demand totals are not additive, and a tile supplied by any network is not counted as unwatered.</p><p>${number(uncovered.length)} demand-bearing tiles lie outside every pipe service area. ${uncovered.length?`<button data-water-location="${uncovered[0]}">View uncovered area</button>`:''}</p><h3>Water source maintenance</h3><div class="table-scroll" style="max-height:360px;overflow:auto"><table><thead><tr><th>Facility / network</th><th>Age / efficiency</th><th>Output</th><th>Pollution loss</th><th>Rebuild cost</th><th>Inspect</th></tr></thead><tbody>${sources.map(p=>`<tr><td>${p.name} · ${p.grid+1}</td><td>${number(p.age/12)} years / ${number(p.efficiency*100)}%</td><td>${p.treatment?p.active?'Treating water':'Treatment inactive':number(p.output)}</td><td>${p.treatment?'—':number(p.loss)}</td><td>§${number(p.cost)}</td><td><button data-water-inspect="${p.tile}">Inspect facility</button></td></tr>`).join('')||'<tr><td colspan="6">No local water facilities. Connected neighbor imports can still supply pipes.</td></tr>'}</tbody></table></div><p>Inspect a source to check electricity, freshwater or coast requirements, and treatment benefits. Replace aging facilities, add capacity for shortages, or extend pipes for uncovered areas. Treatment cleans a connected grid but does not pump water. Rebuild costs exclude demolition.</p>`;}
export function installWaterGridLinks(city,visit,root=document){for(const [attribute,inspect]of [['water-location',false],['water-inspect',true]])root.querySelectorAll(`[data-${attribute}]`).forEach(button=>{button.onclick=()=>{const index=Number(button.getAttribute('data-'+attribute)),tile=city.tiles[index];if(!Number.isInteger(index)||!tile)return;visit({x:tile.x,y:tile.y},inspect);};});}
